export interface IntegerSpan {
  start: number;
  end: number;
}

function validateSpan(span: IntegerSpan): void {
  if (
    typeof span !== "object" ||
    span === null ||
    !Number.isSafeInteger(span.start) ||
    !Number.isSafeInteger(span.end) ||
    span.start > span.end
  ) {
    throw new RangeError("invalid integer span");
  }
}

export function coalesceSpans(
  spans: readonly IntegerSpan[],
): IntegerSpan[] {
  const ordered = spans.map((span) => {
    validateSpan(span);
    return { start: span.start, end: span.end };
  });
  ordered.sort((a, b) => a.start - b.start || a.end - b.end);

  const result: IntegerSpan[] = [];
  for (const span of ordered) {
    const previous = result[result.length - 1];
    if (previous !== undefined && span.start <= previous.end) {
      previous.end = Math.max(previous.end, span.end);
    } else {
      result.push({ ...span });
    }
  }
  return result;
}

export function containsValue(
  spans: readonly IntegerSpan[],
  value: number,
): boolean {
  if (!Number.isSafeInteger(value)) {
    throw new RangeError("value must be a safe integer");
  }
  let found = false;
  for (const span of spans) {
    validateSpan(span);
    if (span.start <= value && value <= span.end) {
      found = true;
    }
  }
  return found;
}

