import { coalesceSpans, containsValue, type IntegerSpan } from "./solution";

function assert(condition: unknown, message: string): asserts condition {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

function spansEqual(actual: readonly IntegerSpan[], expected: readonly IntegerSpan[], message: string): void {
  equal(actual.length, expected.length, `${message} length`);
  for (let i = 0; i < expected.length; i += 1) {
    equal(actual[i].start, expected[i].start, `${message} start ${i}`);
    equal(actual[i].end, expected[i].end, `${message} end ${i}`);
  }
}

function throwsRange(fn: () => unknown, message: string): void {
  try {
    fn();
  } catch (error) {
    assert(error instanceof RangeError, message);
    return;
  }
  throw new Error(`${message}: did not throw`);
}

const input: IntegerSpan[] = [
  { start: 10, end: 12 },
  { start: 1, end: 3 },
  { start: 4, end: 7 },
  { start: 6, end: 9 },
  { start: 20, end: 20 },
];
const snapshot = input.map((span) => ({ ...span }));
const result = coalesceSpans(input);
spansEqual(result, [{ start: 1, end: 12 }, { start: 20, end: 20 }], "sorts and merges overlap and adjacency");
spansEqual(input, snapshot, "does not mutate or sort input");
assert(result[0] !== input[0] && result[0] !== input[1], "does not reuse merged input objects");
assert(result[1] !== input[4], "does not reuse unmerged input objects");
result[1].start = 99;
equal(input[4].start, 20, "output mutation cannot affect input");

const empty = coalesceSpans([]);
equal(empty.length, 0, "empty input yields empty output");

assert(containsValue(input, 1), "contains inclusive lower endpoint");
assert(containsValue(input, 12), "contains inclusive upper endpoint");
assert(!containsValue(input, 13), "reports missing value");
assert(!containsValue([], 0), "empty spans contain nothing");
spansEqual(input, snapshot, "containsValue does not mutate input");

for (const value of [1.5, Number.MAX_SAFE_INTEGER + 1, Infinity, NaN]) {
  throwsRange(() => containsValue([], value), `rejects invalid query ${String(value)}`);
}

const invalidSpans: IntegerSpan[] = [
  { start: 5, end: 4 },
  { start: 0.5, end: 2 },
  { start: 0, end: Infinity },
  { start: Number.MAX_SAFE_INTEGER + 1, end: Number.MAX_SAFE_INTEGER + 1 },
];
for (const span of invalidSpans) {
  throwsRange(() => coalesceSpans([span]), "coalesce rejects malformed span");
}

throwsRange(
  () => containsValue([{ start: 0, end: 10 }, { start: 3, end: 2 }], 5),
  "containsValue validates later spans after finding a match",
);

